/// <summary>
/// Extension class for the ProdParameters table.
/// </summary>
[ExtensionOf(tableStr(ProdParameters))]
final class AVARUMProdParametersTbl_Extension
{
}

Method.Source:
/// <summary>
/// Validates the specified field.
/// </summary>
/// <param name = "_fieldIdToCheck">The field ID to check.</param>
/// <returns>True if the field is valid; otherwise, false.</returns>
public boolean validateField(FieldId _fieldIdToCheck)
{
    boolean ret;

    ret = next validateField(_fieldIdToCheck);

    switch (_fieldIdToCheck)
    {
        case fieldNum(ProdParameters, AVARUMSenderEmail):
            if (this.AVARUMSenderEmail && !Global::validateEMail_AVA(this.AVARUMSenderEmail))
            {
                ret = false;
                Global::error(strFmt("@AVARUM:EmailInvalid", this.AVARUMSenderEmail));
            }
            break;
    }

    return ret;
}
